1	/**
2	 * Sitewave — Site IR (Intermediate Representation) + section-schema types and
3	 * validation.
4	 *
5	 * The generator (lib/agency/generate.ts) emits a Site IR, NOT raw HTML. The
6	 * deterministic renderer (lib/agency/render.ts) maps a validated IR to a
7	 * self-contained static HTML page. Validation lives here so both the LLM path
8	 * and the fallback path produce the exact same, safe shape.
9	 *
10	 * This module is pure (no imports of db / next / anthropic) so it can be unit
11	 * tested and reused server-side without side effects.
12	 */
13	
14	// ---------------------------------------------------------------------------
15	// Section schema — what a vertical template constrains the generated site to.
16	// ---------------------------------------------------------------------------
17	
18	export type SectionKey = "hero" | "services" | "about" | "testimonials" | "contact";
19	
20	export const SECTION_KEYS: SectionKey[] = ["hero", "services", "about", "testimonials", "contact"];
21	
22	export type SectionSchemaEntry = {
23	  key: SectionKey;
24	  label: string;
25	  required: boolean;
26	  /** Human guidance fed to the LLM for this section's copy. */
27	  guidance: string;
28	};
29	
30	export type TemplateStructure = {
31	  sections: SectionSchemaEntry[];
32	  /** Optional palette hint the template suggests to the generator. */
33	  palette?: { primary?: string; accent?: string };
34	};
35	
36	/** Narrow an unknown Json value from Prisma into a TemplateStructure, defensively. */
37	export function asTemplateStructure(value: unknown): TemplateStructure {
38	  const v = (value ?? {}) as { sections?: unknown; palette?: unknown };
39	  const rawSections = Array.isArray(v.sections) ? v.sections : [];
40	  const sections: SectionSchemaEntry[] = rawSections
41	    .map((s) => s as Partial<SectionSchemaEntry>)
42	    .filter((s): s is SectionSchemaEntry => typeof s?.key === "string" && SECTION_KEYS.includes(s.key as SectionKey))
43	    .map((s) => ({
44	      key: s.key,
45	      label: String(s.label ?? s.key),
46	      required: Boolean(s.required),
47	      guidance: String(s.guidance ?? ""),
48	    }));
49	  const palette = (v.palette ?? undefined) as TemplateStructure["palette"];
50	  return { sections, palette };
51	}
52	
53	// ---------------------------------------------------------------------------
54	// Site IR — the structured output the generator produces.
55	// ---------------------------------------------------------------------------
56	
57	export type IRService = { name: string; description: string };
58	export type IRTestimonial = { quote: string; author: string };
59	
60	export type SiteIR = {
61	  businessName: string;
62	  vertical: string;
63	  hero: { headline: string; subheadline: string; ctaLabel: string };
64	  services: IRService[];
65	  about: string;
66	  testimonials: IRTestimonial[];
67	  contact: { ctaHeadline: string; ctaBody: string; buttonLabel: string };
68	  /** A suggested — INSPIRED-BY, not exact-brand — palette (legal guardrail). */
69	  palette: { primary: string; accent: string };
70	};
71	
72	const HEX = /^#[0-9a-fA-F]{6}$/;
73	
74	function str(v: unknown, fallback = ""): string {
75	  return typeof v === "string" && v.trim() ? v.trim() : fallback;
76	}
77	
78	function clampArray<T>(v: unknown, map: (x: unknown) => T | null, max: number): T[] {
79	  if (!Array.isArray(v)) return [];
80	  const out: T[] = [];
81	  for (const item of v) {
82	    const m = map(item);
83	    if (m) out.push(m);
84	    if (out.length >= max) break;
85	  }
86	  return out;
87	}
88	
89	/**
90	 * Coerce an arbitrary object (LLM JSON or a fallback build) into a fully-valid
91	 * SiteIR. NEVER throws: every field is defaulted so the renderer always has a
92	 * safe, complete IR. `defaults` supplies sensible per-vertical text when a field
93	 * is missing (used by the deterministic fallback).
94	 */
95	export function coerceSiteIR(
96	  raw: unknown,
97	  defaults: { businessName: string; vertical: string; palette?: { primary: string; accent: string } }
98	): SiteIR {
99	  const o = (raw ?? {}) as Record<string, unknown>;
100	  const hero = (o.hero ?? {}) as Record<string, unknown>;
101	  const contact = (o.contact ?? {}) as Record<string, unknown>;
102	  const paletteIn = (o.palette ?? {}) as Record<string, unknown>;
103	
104	  const primary = HEX.test(str(paletteIn.primary)) ? str(paletteIn.primary) : (defaults.palette?.primary ?? "#4F46E5");
105	  const accent = HEX.test(str(paletteIn.accent)) ? str(paletteIn.accent) : (defaults.palette?.accent ?? "#FB7185");
106	
107	  return {
108	    businessName: str(o.businessName, defaults.businessName),
109	    vertical: str(o.vertical, defaults.vertical),
110	    hero: {
111	      headline: str(hero.headline, `${defaults.businessName}`),
112	      subheadline: str(hero.subheadline, "A better website, built to win you customers."),
113	      ctaLabel: str(hero.ctaLabel, "Get in touch"),
114	    },
115	    services: clampArray<IRService>(
116	      o.services,
117	      (x) => {
118	        const s = (x ?? {}) as Record<string, unknown>;
119	        const name = str(s.name);
120	        if (!name) return null;
121	        return { name, description: str(s.description, "") };
122	      },
123	      8
124	    ),
125	    about: str(o.about, ""),
126	    testimonials: clampArray<IRTestimonial>(
127	      o.testimonials,
128	      (x) => {
129	        const t = (x ?? {}) as Record<string, unknown>;
130	        const quote = str(t.quote);
131	        if (!quote) return null;
132	        return { quote, author: str(t.author, "Happy customer") };
133	      },
134	      6
135	    ),
136	    contact: {
137	      ctaHeadline: str(contact.ctaHeadline, "Ready to get started?"),
138	      ctaBody: str(contact.ctaBody, "Reach out and we'll get back to you shortly."),
139	      buttonLabel: str(contact.buttonLabel, "Contact us"),
140	    },
141	    palette: { primary, accent },
142	  };
143	}
144	
145	/** True when an IR has the minimum content to render a credible page. */
146	export function isRenderableIR(ir: SiteIR): boolean {
147	  return Boolean(ir.hero.headline) && ir.services.length > 0 && Boolean(ir.contact.ctaHeadline);
148	}
149	
150	/** Slugify a business name into a subdomain-safe label. */
151	export function slugify(input: string): string {
152	  const s = input
153	    .toLowerCase()
154	    .normalize("NFKD")
155	    .replace(/[^a-z0-9]+/g, "-")
156	    .replace(/^-+|-+$/g, "")
157	    .slice(0, 48);
158	  return s || "demo";
159	}
160

1	/**
2	 * Sitewave — DETERMINISTIC renderer: Site IR -> self-contained static HTML.
3	 *
4	 * Pure + deterministic (same IR in => byte-identical HTML out, no clock, no
5	 * randomness, no network). Produces a single self-contained page: inline CSS,
6	 * no external requests, no re-hosted assets.
7	 *
8	 * LEGAL GUARDRAILS baked in (architecture §11 — the biggest risk):
9	 *  - The business NAME appears in plain type only. No logo is referenced or
10	 *    re-hosted.
11	 *  - An INSPIRED-BY / neutral palette (from the IR's palette suggestion) — the
12	 *    renderer never claims to reproduce the business's exact brand.
13	 *  - A visible "Independent concept — not affiliated with {business}" disclaimer
14	 *    in the header banner AND the footer.
15	 *  - <meta name="robots" content="noindex, nofollow"> so the demo can never rank
16	 *    or be mistaken for the real site.
17	 *
18	 * All IR-derived text is HTML-escaped — the renderer never injects raw markup.
19	 */
20	
21	import type { SiteIR } from "./schema";
22	import { SITEWAVE, disclaimerFor } from "./config";
23	
24	/** Escape the five HTML-significant characters. */
25	export function esc(s: string): string {
26	  return String(s)
27	    .replace(/&/g, "&amp;")
28	    .replace(/</g, "&lt;")
29	    .replace(/>/g, "&gt;")
30	    .replace(/"/g, "&quot;")
31	    .replace(/'/g, "&#39;");
32	}
33	
34	/** Sanitize a hex color to a safe `#rrggbb`, else a neutral default. */
35	function safeHex(v: string, fallback: string): string {
36	  return /^#[0-9a-fA-F]{6}$/.test(v) ? v : fallback;
37	}
38	
39	export type RenderResult = {
40	  html: string;
41	  /** True when every mandatory legal guardrail is present in the output. */
42	  guardrailsOk: boolean;
43	};
44	
45	/**
46	 * Render a validated Site IR to a complete HTML document string. Never throws.
47	 */
48	export function renderSiteHtml(ir: SiteIR): RenderResult {
49	  const name = esc(ir.businessName || "This business");
50	  const primary = safeHex(ir.palette.primary, SITEWAVE.palette.indigo);
51	  const accent = safeHex(ir.palette.accent, SITEWAVE.palette.coral);
52	  const disclaimer = esc(disclaimerFor(ir.businessName));
53	  const year = 2026; // fixed so output is deterministic (no Date.now()).
54	
55	  const services = ir.services
56	    .map(
57	      (s) => `        <div class="card">
58	          <h3>${esc(s.name)}</h3>
59	          <p>${esc(s.description)}</p>
60	        </div>`
61	    )
62	    .join("\n");
63	
64	  const testimonials = ir.testimonials
65	    .map(
66	      (t) => `        <figure class="quote">
67	          <blockquote>&ldquo;${esc(t.quote)}&rdquo;</blockquote>
68	          <figcaption>${esc(t.author)}</figcaption>
69	        </figure>`
70	    )
71	    .join("\n");
72	
73	  const aboutBlock = ir.about
74	    ? `    <section id="about" class="section">
75	      <div class="wrap narrow">
76	        <h2>About ${name}</h2>
77	        <p class="lead">${esc(ir.about)}</p>
78	      </div>
79	    </section>`
80	    : "";
81	
82	  const testimonialsBlock = ir.testimonials.length
83	    ? `    <section id="testimonials" class="section alt">
84	      <div class="wrap">
85	        <h2>What people say</h2>
86	        <div class="quotes">
87	${testimonials}
88	        </div>
89	        <p class="fineprint">Illustrative testimonials for this concept — not real customer statements.</p>
90	      </div>
91	    </section>`
92	    : "";
93	
94	  const html = `<!DOCTYPE html>
95	<html lang="en">
96	<head>
97	  <meta charset="utf-8">
98	  <meta name="viewport" content="width=device-width, initial-scale=1">
99	  <meta name="robots" content="noindex, nofollow">
100	  <title>${name} — concept redesign by ${esc(SITEWAVE.name)}</title>
101	  <style>
102	    :root { --primary: ${primary}; --accent: ${accent}; --ink: ${SITEWAVE.palette.ink}; }
103	    * { box-sizing: border-box; }
104	    html, body { margin: 0; padding: 0; }
105	    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; color: #1f2430; line-height: 1.6; background: #fff; }
106	    a { color: var(--primary); }
107	    .wrap { max-width: 1080px; margin: 0 auto; padding: 0 24px; }
108	    .narrow { max-width: 760px; }
109	    .disclaimer-bar { background: var(--ink); color: #cdd3e0; font-size: 13px; text-align: center; padding: 8px 16px; }
110	    header.hero { background: linear-gradient(135deg, var(--primary), var(--accent)); color: #fff; padding: 96px 0 88px; text-align: center; }
111	    header.hero h1 { font-size: clamp(32px, 6vw, 56px); margin: 0 0 16px; line-height: 1.1; }
112	    header.hero p { font-size: clamp(17px, 2.4vw, 22px); max-width: 640px; margin: 0 auto 28px; opacity: .95; }
113	    .btn { display: inline-block; background: #fff; color: var(--primary); font-weight: 700; text-decoration: none; padding: 14px 28px; border-radius: 999px; }
114	    .btn.solid { background: var(--primary); color: #fff; }
115	    .brandline { text-transform: uppercase; letter-spacing: .18em; font-size: 13px; opacity: .85; margin: 0 0 20px; }
116	    .section { padding: 72px 0; }
117	    .section.alt { background: #f6f7fb; }
118	    .section h2 { font-size: clamp(26px, 4vw, 38px); margin: 0 0 32px; text-align: center; }
119	    .lead { font-size: 19px; text-align: center; color: #3a4152; }
120	    .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 20px; }
121	    .card { background: #fff; border: 1px solid #e7e9f2; border-radius: 16px; padding: 24px; }
122	    .card h3 { margin: 0 0 8px; color: var(--primary); font-size: 19px; }
123	    .card p { margin: 0; color: #4a5162; }
124	    .quotes { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 20px; }
125	    .quote { margin: 0; background: #fff; border: 1px solid #e7e9f2; border-radius: 16px; padding: 24px; }
126	    .quote blockquote { margin: 0 0 12px; font-size: 18px; color: #2a3040; }
127	    .quote figcaption { color: #7a8194; font-weight: 600; }
128	    .fineprint { text-align: center; color: #9aa0b0; font-size: 13px; margin-top: 24px; }
129	    .cta { background: var(--ink); color: #fff; text-align: center; padding: 80px 0; }
130	    .cta h2 { margin: 0 0 12px; color: #fff; }
131	    .cta p { max-width: 560px; margin: 0 auto 28px; color: #cdd3e0; }
132	    footer.site { background: #0b1020; color: #8b93a7; padding: 40px 0; font-size: 13px; text-align: center; }
133	    footer.site strong { color: #cdd3e0; }
134	  </style>
135	</head>
136	<body>
137	  <div class="disclaimer-bar">${disclaimer}</div>
138	
139	  <header class="hero">
140	    <div class="wrap">
141	      <p class="brandline">${name}</p>
142	      <h1>${esc(ir.hero.headline)}</h1>
143	      <p>${esc(ir.hero.subheadline)}</p>
144	      <a class="btn" href="#contact">${esc(ir.hero.ctaLabel)}</a>
145	    </div>
146	  </header>
147	
148	  <main>
149	    <section id="services" class="section">
150	      <div class="wrap">
151	        <h2>Our services</h2>
152	        <div class="grid">
153	${services}
154	        </div>
155	      </div>
156	    </section>
157	
158	${aboutBlock}
159	
160	${testimonialsBlock}
161	
162	    <section id="contact" class="cta">
163	      <div class="wrap narrow">
164	        <h2>${esc(ir.contact.ctaHeadline)}</h2>
165	        <p>${esc(ir.contact.ctaBody)}</p>
166	        <a class="btn solid" href="#contact">${esc(ir.contact.buttonLabel)}</a>
167	      </div>
168	    </section>
169	  </main>
170	
171	  <footer class="site">
172	    <div class="wrap">
173	      <p><strong>${disclaimer}</strong></p>
174	      <p>Concept redesign &middot; ${esc(SITEWAVE.name)} &middot; ${SITEWAVE.tagline} &middot; &copy; ${year}</p>
175	    </div>
176	  </footer>
177	</body>
178	</html>`;
179	
180	  // Assert every mandatory guardrail actually made it into the output.
181	  const guardrailsOk =
182	    html.includes('name="robots"') &&
183	    html.includes("noindex") &&
184	    html.includes("Independent concept — not affiliated with") &&
185	    html.includes(esc(SITEWAVE.name));
186	
187	  return { html, guardrailsOk };
188	}
189

1	/**
2	 * Sitewave — spec-site GENERATOR core.
3	 *
4	 * Given a prospect (business name, vertical, optional PASTED existing-site text
5	 * — never scraped), produce a structured Site IR constrained to the vertical's
6	 * section schema. Uses the platform Anthropic key via lib/anthropic.ts (askClaude).
7	 *
8	 * Degrades gracefully, exactly like lib/marketing/draft-gen.ts: if no
9	 * ANTHROPIC_API_KEY is configured (or the call fails / returns unusable JSON),
10	 * it falls back to the deterministic per-vertical template fill so a demo is
11	 * ALWAYS produced. Every path returns a fully-valid, coerced SiteIR.
12	 *
13	 * This module performs NO scraping and NO network fetch of the prospect's site —
14	 * `pastedSiteText` is operator-supplied context only.
15	 */
16	
17	import { askClaude, platformKeyConfigured } from "../anthropic";
18	import { coerceSiteIR, type SiteIR, type TemplateStructure } from "./schema";
19	import { fallbackIR, verticalBySlug } from "./templates";
20	import { SITEWAVE } from "./config";
21	
22	const GEN_MODEL = "claude-opus-4-8";
23	
24	export type GenerateInput = {
25	  businessName: string;
26	  vertical: string;
27	  slug: string;
28	  pastedSiteText?: string;
29	  structure?: TemplateStructure;
30	};
31	
32	export type GenerateResult = {
33	  ir: SiteIR;
34	  /** "llm" when askClaude produced usable JSON, else "fallback". */
35	  mode: "llm" | "fallback";
36	  model: string;
37	  ok: boolean;
38	  message: string;
39	};
40	
41	function buildSystemPrompt(structure: TemplateStructure | undefined, vertical: string): string {
42	  const v = verticalBySlug(vertical);
43	  const sectionList = (structure?.sections ?? [])
44	    .map((s) => `- ${s.key}${s.required ? " (required)" : ""}: ${s.guidance}`)
45	    .join("\n");
46	
47	  return `You are a senior web copywriter for ${SITEWAVE.name}, a web-design studio. You write a concept redesign for a local ${v?.name ?? vertical} business.
48	
49	You output ONLY a single JSON object (no prose, no markdown fences) matching this exact shape:
50	{
51	  "businessName": string,
52	  "vertical": string,
53	  "hero": { "headline": string, "subheadline": string, "ctaLabel": string },
54	  "services": [ { "name": string, "description": string } ],   // 3 to 6 items
55	  "about": string,
56	  "testimonials": [ { "quote": string, "author": string } ],   // 2 to 3 items
57	  "contact": { "ctaHeadline": string, "ctaBody": string, "buttonLabel": string },
58	  "palette": { "primary": "#RRGGBB", "accent": "#RRGGBB" }
59	}
60	
61	Section guidance:
62	${sectionList || "- hero, services, about, testimonials, contact"}
63	
64	${v?.promptHint ? `Vertical tone: ${v.promptHint}` : ""}
65	
66	HARD RULES (legal + quality):
67	1. Use the business name as PLAIN TEXT only. Never describe or reference a logo.
68	2. palette must be an INSPIRED-BY scheme appropriate to the vertical — do NOT try to reproduce the business's exact brand colors. Return valid 6-digit hex.
69	3. testimonials must be GENERIC and clearly illustrative — never invent named real people or fabricate specific verifiable claims (no fake star counts, awards, or statistics).
70	4. Rewrite everything in fresh words. Never copy sentences verbatim from any provided existing-site text.
71	5. Keep copy concise and benefit-led. Output must be valid JSON and nothing else.`;
72	}
73	
74	/** Pull the first balanced top-level JSON object out of a model reply. */
75	function extractJson(text: string): unknown | null {
76	  const trimmed = text.trim();
77	  // Fast path: the whole reply is JSON.
78	  try {
79	    return JSON.parse(trimmed);
80	  } catch {
81	    // fall through to brace scan
82	  }
83	  const start = trimmed.indexOf("{");
84	  if (start < 0) return null;
85	  let depth = 0;
86	  let inStr = false;
87	  let esc = false;
88	  for (let i = start; i < trimmed.length; i++) {
89	    const c = trimmed[i];
90	    if (inStr) {
91	      if (esc) esc = false;
92	      else if (c === "\\") esc = true;
93	      else if (c === '"') inStr = false;
94	      continue;
95	    }
96	    if (c === '"') inStr = true;
97	    else if (c === "{") depth++;
98	    else if (c === "}") {
99	      depth--;
100	      if (depth === 0) {
101	        const slice = trimmed.slice(start, i + 1);
102	        try {
103	          return JSON.parse(slice);
104	        } catch {
105	          return null;
106	        }
107	      }
108	    }
109	  }
110	  return null;
111	}
112	
113	/**
114	 * Generate a Site IR for a prospect. Never throws; always returns a renderable
115	 * IR. When `mode === "fallback"` the deterministic per-vertical fill was used.
116	 */
117	export async function generateSiteIR(input: GenerateInput): Promise<GenerateResult> {
118	  const vertical = input.vertical.trim() || "dentist";
119	  const seed = verticalBySlug(vertical) ?? verticalBySlug("dentist")!;
120	  const defaults = {
121	    businessName: input.businessName.trim() || seed.name,
122	    vertical: seed.slug,
123	    palette: seed.fallback.palette,
124	  };
125	  const fallback: GenerateResult = {
126	    ir: fallbackIR(input.businessName, seed.slug),
127	    mode: "fallback",
128	    model: "",
129	    ok: true,
130	    message: "Deterministic template fill (no LLM).",
131	  };
132	
133	  if (!platformKeyConfigured()) {
134	    return { ...fallback, message: "No ANTHROPIC_API_KEY configured — used deterministic template fill." };
135	  }
136	
137	  const key = process.env.ANTHROPIC_API_KEY!.trim();
138	  const structure = input.structure ?? seed.structure;
139	  const system = buildSystemPrompt(structure, seed.slug);
140	
141	  const pasted = (input.pastedSiteText ?? "").trim().slice(0, 4000);
142	  const userMsg =
143	    `Business name: ${input.businessName.trim() || "(unnamed)"}\n` +
144	    `Vertical: ${seed.name}\n` +
145	    (pasted
146	      ? `\nContext pasted from their existing site (rewrite, do NOT copy):\n"""\n${pasted}\n"""\n`
147	      : `\n(No existing-site text provided — write from the vertical alone.)\n`) +
148	    `\nReturn the JSON object now.`;
149	
150	  let text: string;
151	  try {
152	    text = await askClaude(key, [{ role: "user", content: userMsg }], system, {
153	      maxTokens: 1800,
154	      timeoutMs: 60_000,
155	    });
156	  } catch (err) {
157	    return { ...fallback, ok: false, message: `LLM call failed, used fallback: ${String(err).slice(0, 200)}` };
158	  }
159	
160	  const parsed = extractJson(text);
161	  if (!parsed) {
162	    return { ...fallback, ok: false, message: "LLM returned unparseable JSON — used fallback." };
163	  }
164	
165	  const ir = coerceSiteIR(parsed, defaults);
166	  // If the model produced no services, prefer the fallback's fuller content.
167	  if (ir.services.length === 0) {
168	    return { ...fallback, ok: false, message: "LLM output had no services — used fallback." };
169	  }
170	
171	  return { ir, mode: "llm", model: GEN_MODEL, ok: true, message: "Generated via Claude." };
172	}
173

1	/**
2	 * Sitewave — PHASE 2 CRM pipeline stage helpers. Pure (no db / next imports) so
3	 * the transition rules are unit-tested and the server action + kanban UI agree.
4	 *
5	 * The pipeline is a simple linear funnel with two terminal states. We allow any
6	 * forward move and a move back one step (an operator correcting a mis-click),
7	 * plus reopening a WON/LOST deal — but we reject nonsense like LEAD -> WON in one
8	 * jump so the funnel stats stay meaningful.
9	 */
10	
11	export const DEAL_STAGES = [
12	  "LEAD",
13	  "CONTACTED",
14	  "DEMO_SENT",
15	  "NEGOTIATING",
16	  "WON",
17	  "LOST",
18	] as const;
19	
20	export type DealStage = (typeof DEAL_STAGES)[number];
21	
22	/** Human labels for the kanban columns (sentence case). */
23	export const STAGE_LABELS: Record<DealStage, string> = {
24	  LEAD: "Lead",
25	  CONTACTED: "Contacted",
26	  DEMO_SENT: "Demo sent",
27	  NEGOTIATING: "Negotiating",
28	  WON: "Won",
29	  LOST: "Lost",
30	};
31	
32	/** The ordered, non-terminal progression a deal walks through. */
33	const PROGRESSION: DealStage[] = ["LEAD", "CONTACTED", "DEMO_SENT", "NEGOTIATING"];
34	
35	export function isDealStage(v: unknown): v is DealStage {
36	  return typeof v === "string" && (DEAL_STAGES as readonly string[]).includes(v);
37	}
38	
39	export function isTerminal(stage: DealStage): boolean {
40	  return stage === "WON" || stage === "LOST";
41	}
42	
43	/**
44	 * Is moving `from` -> `to` a legal transition?
45	 *
46	 * Rules:
47	 *  - staying put is a no-op, always allowed;
48	 *  - from any non-terminal stage you may advance any number of steps forward,
49	 *    step back exactly one, or close the deal (WON / LOST);
50	 *  - a terminal deal (WON / LOST) may be REOPENED to any non-terminal stage, or
51	 *    flipped between WON and LOST;
52	 *  - anything else is rejected.
53	 */
54	export function canTransition(from: DealStage, to: DealStage): boolean {
55	  if (!isDealStage(from) || !isDealStage(to)) return false;
56	  if (from === to) return true;
57	
58	  // Terminal -> reopen to a non-terminal, or WON<->LOST.
59	  if (isTerminal(from)) {
60	    if (!isTerminal(to)) return true;
61	    return true; // WON <-> LOST flip
62	  }
63	
64	  // Non-terminal -> terminal is always allowed (close the deal).
65	  if (isTerminal(to)) return true;
66	
67	  // Non-terminal -> non-terminal: forward any distance, or back exactly one.
68	  const fi = PROGRESSION.indexOf(from);
69	  const ti = PROGRESSION.indexOf(to);
70	  if (fi < 0 || ti < 0) return false;
71	  if (ti > fi) return true; // forward
72	  return fi - ti === 1; // back one step only
73	}
