211	// ---------------------------------------------------------------------------
212	// Pinned dispatcher — close the DNS-rebinding TOCTOU window.
213	// ---------------------------------------------------------------------------
214	
215	/**
216	 * An undici Agent whose DNS resolution is hard-wired to an already-vetted
217	 * address. The URL still supplies the Host header + TLS SNI, so virtual hosts
218	 * and certificate validation behave normally — only the address we dial is
219	 * fixed, to the exact IP `assertHostPublic` just approved. Without this, undici
220	 * re-resolves the hostname on connect and a 0-TTL record that answered public on
221	 * the check can answer 127.0.0.1 / 169.254.169.254 / 10.x on the connect.
222	 *
223	 * undici's connector calls `lookup` with `{ all: true }` and expects an ARRAY of
224	 * `{ address, family }`; node's `net.connect` contract is the positional
225	 * `(err, address, family)` form. Both shapes are answered here (mirrors the
226	 * http-headers tool) — getting it wrong fails every request at runtime, not at
227	 * build time.
228	 */
229	type LookupCallback = (err: Error | null, addresses: unknown, family?: number) => void;
230	
231	function pinnedAgent(address: string): Agent {
232	  const family = isIP(address);
233	  return new Agent({
234	    connect: {
235	      lookup: (_hostname: string, options: { all?: boolean }, callback: LookupCallback) => {
236	        if (options?.all) callback(null, [{ address, family }]);
237	        else callback(null, address, family);
238	      },
239	    } as never,
240	  });
241	}
