322	/** Extract light brand signals from a page's HTML. Pure + deterministic. */
323	export function extractFromHtml(html: string): ScrapeExtraction {
324	  const src = String(html);
325	
326	  // Strip script/style/noscript before pulling any visible text.
327	  const stripped = src
328	    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ")
329	    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ")
330	    .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, " ")
331	    .replace(/<!--[\s\S]*?-->/g, " ");
332	
333	  const titleRaw = /<title[^>]*>([\s\S]*?)<\/title>/i.exec(src)?.[1] ?? "";
334	  const title = tidy(titleRaw);
335	  const ogSite = metaContent(src, /og:site_name/i);
336	  const ogTitle = metaContent(src, /og:title/i);
337	  const description = metaContent(src, /^(description|og:description)$/i);
338	
339	  const h1 = /<h1\b[^>]*>([\s\S]*?)<\/h1>/i.exec(stripped);
340	  const h1Text = h1 ? tidy(h1[1].replace(/<[^>]+>/g, " ")) : "";
341	
342	  // Business name: prefer og:site_name, else the title's leading segment, else h1.
343	  let businessName = ogSite;
344	  if (!businessName && title) {
345	    businessName = title.split(/\s*[|\-–—:·]\s*/)[0].trim();
346	  }
347	  if (!businessName) businessName = h1Text;
348	  businessName = businessName.slice(0, 120);
349	
350	  // Tagline: og:description / meta description / the title remainder.
351	  let tagline = description || ogTitle || "";
352	  if (!tagline && title.includes("|")) tagline = title.split("|").slice(1).join("|").trim();
353	  tagline = tidy(tagline).slice(0, 200);
354	
355	  // Headings (h1..h3) — candidates for services + hero copy.
356	  const headings: string[] = [];
357	  const hRe = /<h([1-3])\b[^>]*>([\s\S]*?)<\/h\1>/gi;
358	  let hm: RegExpExecArray | null;
359	  while ((hm = hRe.exec(stripped)) && headings.length < 40) {
360	    const t = tidy(hm[2].replace(/<[^>]+>/g, " "));
361	    if (t && t.length <= 120) headings.push(t);
362	  }
363	
364	  // Services: h2/h3 headings + <li> items that read like offerings.
365	  const liRe = /<li\b[^>]*>([\s\S]*?)<\/li>/gi;
366	  const lis: string[] = [];
367	  let lm: RegExpExecArray | null;
368	  while ((lm = liRe.exec(stripped)) && lis.length < 60) {
369	    const t = tidy(lm[1].replace(/<[^>]+>/g, " "));
370	    if (t && t.length >= 3 && t.length <= 80) lis.push(t);
371	  }
372	  const subHeads = headings.filter((h) => h !== h1Text);
373	  const services = unique([...subHeads, ...lis], 12);
374	
375	  // Contact — emails (mailto: + bare) and phones (tel: + bare NA/intl pattern).
376	  const emails = unique(
377	    [
378	      ...Array.from(src.matchAll(/mailto:([^"'?\s>]+)/gi), (m) => m[1]),
379	      ...Array.from(src.matchAll(/[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/g), (m) => m[0]),
380	    ].filter((e) => !/\.(png|jpe?g|gif|svg|webp)$/i.test(e)),
381	    6
382	  );
383	  const phones = unique(
384	    [
385	      ...Array.from(src.matchAll(/tel:([+0-9().\-\s]{6,})/gi), (m) => m[1].trim()),
386	      ...Array.from(
387	        stripped.matchAll(/(\+?\d[\d().\-\s]{7,}\d)/g),
388	        (m) => m[1].trim()
389	      ).filter((p) => (p.match(/\d/g) ?? []).length >= 7 && (p.match(/\d/g) ?? []).length <= 15),
390	    ],
391	    6
392	  );
393	
394	  // Colour hint: theme-color meta first, else the first hex in an inline style.
395	  let colorHint = metaContent(src, /theme-color/i);
396	  if (!/^#[0-9a-fA-F]{6}$/.test(colorHint)) {
397	    const hex = /(?:color|background(?:-color)?)\s*:\s*(#[0-9a-fA-F]{6})\b/i.exec(src);
398	    colorHint = hex ? hex[1] : "";
399	  }
400	  if (!/^#[0-9a-fA-F]{6}$/.test(colorHint)) colorHint = "";
401	
402	  // A condensed visible-text sample for the generator (rewrites, never copies).
403	  const textSample = tidy(stripped.replace(/<[^>]+>/g, " ")).slice(0, 4000);
404	
405	  return {
406	    businessName,
407	    tagline,
408	    headings: unique(headings, 20),
409	    services,
410	    emails,
411	    phones,
412	    colorHint: colorHint.toLowerCase(),
413	    textSample,
414	  };
415	}
