417	/** Join the extraction into the pastedSiteText the generator rewrites from. */
418	export function extractionToPastedText(x: ScrapeExtraction): string {
419	  const parts: string[] = [];
420	  if (x.businessName) parts.push(`Business: ${x.businessName}`);
421	  if (x.tagline) parts.push(`Tagline: ${x.tagline}`);
422	  if (x.services.length) parts.push(`Services / sections:\n- ${x.services.join("\n- ")}`);
423	  if (x.headings.length) parts.push(`Headings:\n- ${x.headings.slice(0, 12).join("\n- ")}`);
424	  if (x.emails.length) parts.push(`Contact emails: ${x.emails.join(", ")}`);
425	  if (x.phones.length) parts.push(`Contact phones: ${x.phones.join(", ")}`);
426	  if (x.textSample) parts.push(`Page text (rewrite, do not copy):\n${x.textSample}`);
427	  return parts.join("\n\n").slice(0, 6000);
428	}
