478	/**
479	 * Fetch a single operator-supplied URL safely and extract brand signals. Never
480	 * throws — returns { ok:false, error } on any refusal or failure. Follows at most
481	 * MAX_REDIRECTS redirects, re-validating each hop's host.
482	 */
483	export async function scrapeSite(rawUrl: string): Promise<ScrapeResult> {
484	  const base: ScrapeResult = {
485	    ok: false,
486	    url: String(rawUrl ?? "").trim(),
487	    finalUrl: "",
488	    status: 0,
489	    bytes: 0,
490	    extraction: emptyExtraction(),
491	    error: "",
492	  };
493	
494	  let current: URL;
495	  try {
496	    current = parseHttpUrl(rawUrl);
497	  } catch (err) {
498	    return { ...base, error: (err as Error).message };
499	  }
500	
501	  const controller = new AbortController();
502	  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);
503	  let agent: Agent | null = null;
504	  try {
505	    for (let hop = 0; hop <= MAX_REDIRECTS; hop++) {
506	      let vettedAddrs: string[];
507	      try {
508	        vettedAddrs = await assertHostPublic(current.hostname);
509	      } catch (err) {
510	        return { ...base, finalUrl: current.toString(), error: (err as Error).message };
511	      }
512	
513	      // Pin THIS hop's connection to the exact IP we just vetted, so undici
514	      // cannot re-resolve the hostname on connect (DNS-rebinding TOCTOU). A fresh
515	      // Agent per hop — a redirect to a new host is re-resolved, re-checked, and
516	      // re-pinned on the next iteration; the previous Agent is closed first.
517	      await agent?.close().catch(() => {});
518	      agent = pinnedAgent(vettedAddrs[0]);
519	
520	      let res: UndiciResponse;
521	      try {
522	        res = await undiciFetch(current.toString(), {
523	          method: "GET",
524	          redirect: "manual",
525	          signal: controller.signal,
526	          dispatcher: agent,
527	          headers: {
528	            "user-agent": USER_AGENT,
529	            accept: "text/html,application/xhtml+xml",
530	            "accept-language": "en",
531	          },
532	        });
533	      } catch (err) {
534	        const msg = controller.signal.aborted ? `Timed out after ${TIMEOUT_MS}ms.` : String((err as Error).message);
535	        return { ...base, finalUrl: current.toString(), error: `Fetch failed: ${msg}` };
536	      }
537	
538	      // Redirect? Re-parse + re-validate the next hop.
539	      if (res.status >= 300 && res.status < 400) {
540	        const loc = res.headers.get("location");
541	        if (!loc) return { ...base, finalUrl: current.toString(), status: res.status, error: "Redirect without a Location." };
542	        if (hop === MAX_REDIRECTS) {
543	          return { ...base, finalUrl: current.toString(), status: res.status, error: `Too many redirects (>${MAX_REDIRECTS}).` };
544	        }
545	        let next: URL;
546	        try {
547	          next = parseHttpUrl(new URL(loc, current).toString());
548	        } catch (err) {
549	          return { ...base, finalUrl: current.toString(), status: res.status, error: `Refused redirect: ${(err as Error).message}` };
550	        }
551	        current = next;
552	        continue;
553	      }
554	
555	      if (!res.ok) {
556	        return { ...base, finalUrl: current.toString(), status: res.status, error: `HTTP ${res.status}.` };
557	      }
558	
559	      const ctype = res.headers.get("content-type") ?? "";
560	      if (ctype && !/text\/html|application\/xhtml|text\/plain/i.test(ctype)) {
561	        return { ...base, finalUrl: current.toString(), status: res.status, error: `Unsupported content-type: ${ctype.split(";")[0]}.` };
562	      }
563	
564	      const { text, bytes } = await readCapped(res);
565	      const extraction = extractFromHtml(text);
566	      return {
567	        ok: true,
568	        url: base.url,
569	        finalUrl: current.toString(),
570	        status: res.status,
571	        bytes,
572	        extraction,
573	        error: "",
574	      };
575	    }
576	    return { ...base, error: `Too many redirects (>${MAX_REDIRECTS}).` };
577	  } finally {
578	    clearTimeout(timer);
579	    // One Agent per request lifetime — close it or its sockets leak.
580	    await agent?.close().catch(() => {});
581	  }
582	}
