791	// CSV parser (server-side, no dependency). Handles quotes, commas, newlines.
792	// ---------------------------------------------------------------------------
793	
794	function parseCsv(text: string): { headers: string[]; rows: string[][] } {
795	  const records: string[][] = [];
796	  let field = "";
797	  let row: string[] = [];
798	  let inQuotes = false;
799	  const src = text.replace(/\r\n?/g, "\n");
800	  for (let i = 0; i < src.length; i++) {
801	    const c = src[i];
802	    if (inQuotes) {
803	      if (c === '"') {
804	        if (src[i + 1] === '"') {
805	          field += '"';
806	          i++;
807	        } else {
808	          inQuotes = false;
809	        }
810	      } else {
811	        field += c;
812	      }
813	    } else if (c === '"') {
814	      inQuotes = true;
815	    } else if (c === ",") {
816	      row.push(field);
817	      field = "";
818	    } else if (c === "\n") {
819	      row.push(field);
820	      records.push(row);
821	      row = [];
822	      field = "";
823	    } else {
824	      field += c;
825	    }
826	  }
827	  if (field.length > 0 || row.length > 0) {
828	    row.push(field);
829	    records.push(row);
830	  }
831	  const nonEmpty = records.filter((r) => r.some((v) => v.trim() !== ""));
832	  if (nonEmpty.length === 0) return { headers: [], rows: [] };
833	  const headers = nonEmpty[0].map((h) => h.trim().toLowerCase());
834	  return { headers, rows: nonEmpty.slice(1) };
835	}
