/**
 * Sitewave — PHASE 2 gated subdomain deploy.
 *
 * This module PRODUCES a self-contained static bundle from a generated demo and
 * describes where it would go. It does NOT itself touch nginx, DNS, certbot, the
 * filesystem, or any hosting node — the bundle builder is pure and deterministic.
 *
 * The server action (lib/actions-agency.ts `deployDemo`) decides the mode:
 *   - DEFAULT (Setting AGENCY_DEPLOY_ENABLED unset/false): records a DEPLOYED_STUB
 *     with the intended host (slug.agency.revsports.ca) and the bundle size. No
 *     infrastructure is provisioned.
 *   - ENABLED (an operator has flipped the Setting on a reviewed environment):
 *     enqueues a real deploy via the platform hosting mechanism.
 *
 * Keeping the bundle build here (pure) means it is unit-testable and identical in
 * both modes.
 */

import { intendedHostFor } from "./config";

export type BundleFile = { path: string; content: string };

export type DeployBundle = {
  /** The files that would be written to the demo's static docroot. */
  files: BundleFile[];
  /** Total size in bytes across all files. */
  bytes: number;
  /** The intended public host for this slug (config only; not resolved). */
  intendedHost: string;
};

/**
 * A robots.txt that reinforces the in-page noindex guardrail: a deployed demo
 * must never be crawled, indexed, or mistaken for the real business site.
 */
export const DEMO_ROBOTS_TXT = "User-agent: *\nDisallow: /\n";

/**
 * Build the static bundle for a demo. Pure + deterministic: same input in ->
 * byte-identical bundle out. Includes the rendered HTML as index.html plus a
 * hard robots.txt.
 */
export function buildDeployBundle(demo: {
  slug: string;
  renderedHtml: string;
}): DeployBundle {
  const files: BundleFile[] = [
    { path: "index.html", content: demo.renderedHtml },
    { path: "robots.txt", content: DEMO_ROBOTS_TXT },
  ];
  const bytes = files.reduce((sum, f) => sum + Buffer.byteLength(f.content, "utf8"), 0);
  return { files, bytes, intendedHost: intendedHostFor(demo.slug) };
}

