60	/** A button that runs a (id) => Promise action inside a transition. */
61	function ActionButton({
62	  run,
63	  children,
64	  className = "",
65	  confirm,
66	  title,
67	}: {
68	  run: () => Promise<State>;
69	  children: React.ReactNode;
70	  className?: string;
71	  confirm?: string;
72	  title?: string;
73	}) {
74	  const [pending, start] = useTransition();
75	  const [err, setErr] = useState<string | null>(null);
76	  return (
77	    <span className="inline-flex flex-col items-end">
78	      <button
79	        type="button"
80	        disabled={pending}
81	        title={title}
82	        className={className || "btn-ghost text-xs"}
83	        onClick={() => {
84	          if (confirm && !window.confirm(confirm)) return;
85	          setErr(null);
86	          start(async () => {
87	            const r = await run();
88	            if (r?.error) setErr(r.error);
89	          });
90	        }}
91	      >
92	        {pending ? "Working…" : children}
93	      </button>
94	      {err && <span className="mt-1 text-[11px] text-red-400">{err}</span>}
95	    </span>
96	  );
97	}
